function nimSum(piles){ var s=0; piles.forEach(function(p){s^=p;}); return s; }
function nimWinning(piles){ return nimSum(piles)!==0; }
function nimBest(piles){ var s=nimSum(piles); if(s===0) return null; for(var i=0;i<piles.length;i++){ if((piles[i]^s) < piles[i]) return {pile:i, take: piles[i]-(piles[i]^s)}; } return null; }
function nimApply(piles, i, take){ var np=piles.slice(); np[i]-=take; return np; }
var EXPORTS={nimSum:nimSum,nimWinning:nimWinning,nimBest:nimBest,nimApply:nimApply};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.NimForgePure = EXPORTS; }
